create extension if not exists pgtap with schema extensions;
begin;
grant atelier_worker to postgres with inherit false;
grant usage on schema extensions to atelier_worker;
select no_plan();
create temp table fixture(key text primary key, value uuid);
grant all on fixture to authenticated, atelier_worker;
create function pg_temp.id(text) returns uuid language sql stable as 'select value from fixture where key=$1';
insert into auth.users(id,email) values ('81000000-0000-4000-8000-000000000001','m8@example.test');
insert into public.accounts(id,name,created_by) values ('82000000-0000-4000-8000-000000000001','M8 fixture','81000000-0000-4000-8000-000000000001');
insert into public.account_memberships(account_id,user_id,role) values ('82000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000001','owner') on conflict do nothing;
set local role authenticated;
select set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000001',true);
with created as (select * from public.create_product_with_revision('Durable fixture',null))
insert into fixture select 'product',product_id from created union all select 'revision',revision_id from created;
with queued as (select * from public.enqueue_phase1_test_build(pg_temp.id('product'),pg_temp.id('revision'),'milestone-eight-test-key'))
insert into fixture select 'job',job_id from queued;
select throws_ok($$select private.worker_execution_context(pg_temp.id('job'),'run_m8')$$,'42501',null,'client cannot read worker context');
set local role atelier_worker;
select throws_ok($$select private.worker_execution_context(pg_temp.id('job'),'run_m8')$$,'55000',null,'unbound run cannot execute');
with claimed as (select * from private.worker_claim_outbox(gen_random_uuid()))
insert into fixture select 'outbox',outbox_id from claimed union all select 'lease',lease_token from claimed;
select private.worker_bind_run(pg_temp.id('outbox'),pg_temp.id('lease'),'run_m8');
select is((select count(*) from private.worker_active_runs(null,100)),1::bigint,'reconciliation lists bound active job');
select throws_ok($$select private.worker_active_runs(null,101)$$,'22023',null,'reconciliation batch bounded');
select throws_ok($$select private.worker_reconcile_execution(pg_temp.id('job'),'run_m8','succeeded')$$,'22023',null,'provider cannot assert completion');
select is(private.worker_execution_context(pg_temp.id('job'),'run_m8')->>'revisionName','Durable fixture','context uses immutable revision');
select throws_ok($$select private.worker_execution_context(pg_temp.id('job'),'wrong_run')$$,'55000',null,'wrong run cannot read context');
select throws_ok($$select private.worker_execution_context(gen_random_uuid(),'run_m8')$$,'55000',null,'nonexistent job rejected');
select throws_ok($$select private.worker_begin_execution(pg_temp.id('job'),'run_m8',0)$$,'22023',null,'invalid ordinal rejected');
insert into fixture values ('attempt1',(private.worker_begin_execution(pg_temp.id('job'),'run_m8',1)->>'attemptId')::uuid);
select is((private.worker_begin_execution(pg_temp.id('job'),'run_m8',1)->>'attemptId')::uuid,pg_temp.id('attempt1'),'interrupted same attempt resumes');
insert into fixture values ('attempt2',(private.worker_begin_execution(pg_temp.id('job'),'run_m8',2)->>'attemptId')::uuid);
select isnt(pg_temp.id('attempt1'),pg_temp.id('attempt2'),'new retry gets distinct database attempt');
select throws_ok($$select private.worker_begin_execution(pg_temp.id('job'),'run_m8',1)$$,'55000',null,'older retry fenced');
select throws_ok($$select private.worker_record_progress(pg_temp.id('job'),pg_temp.id('attempt1'),50,'Stale')$$,'55000',null,'stale worker cannot progress');
select private.worker_fail_attempt(pg_temp.id('job'),pg_temp.id('attempt2'),'test_failure','Safe failure',false);
select throws_ok($$select private.worker_begin_execution(pg_temp.id('job'),'run_m8',2)$$,'55000',null,'failed ordinal cannot replay');
select lives_ok($$select private.worker_begin_execution(pg_temp.id('job'),'run_m8',3)$$,'new ordinal retries after failure');
select throws_ok($$select private.worker_reconcile_execution(pg_temp.id('job'),'wrong_run','failed')$$,'55000',null,'wrong run cannot reconcile');
select lives_ok($$select private.worker_reconcile_execution(pg_temp.id('job'),'run_m8','canceled')$$,'provider cancellation reconciles');
select lives_ok($$select private.worker_reconcile_execution(pg_temp.id('job'),'run_m8','canceled')$$,'cancellation replay is idempotent');
select throws_ok($$select private.worker_begin_execution(pg_temp.id('job'),'run_m8',4)$$,'55000',null,'canceled job cannot restart');
select is((select count(*) from private.worker_active_runs(null,100)),0::bigint,'terminal jobs leave reconciliation scan');
reset role;
select is((select status from public.jobs where id=pg_temp.id('job')),'canceled','database records cancellation');
select is((select count(*) from public.job_attempts where job_id=pg_temp.id('job') and outcome='running'),0::bigint,'cancellation retires all running attempts');
select is((select count(*) from public.artifacts where job_id=pg_temp.id('job')),0::bigint,'failed attempts never fabricate artifact');
select * from finish();
rollback;
